   "newText": "def transform(grid):
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    # Endpoint bars mark the two sides of a region. Fill inward at each
    # row/column by the bar's color, except where the interior marker stops it.
    bg=max(set(x for row in grid for x in row), key=lambda x: sum(row.count(x) for row in grid))
    edge_colors=[x for row in grid for x in (row[0],row[-1]) if x!=bg]
    if not edge_colors: edge_colors=[x for x in grid[0] if x!=bg]
    fill=min(edge_colors) if edge_colors else bg
    # Identify the edge runs and propagate their color toward the center;
    # foreground marker 8/1/3 is changed to 4 at its endpoint.
    left=[r for r in range(h) if grid[r][0]!=bg]
    right=[r for r in range(h) if grid[r][-1]!=bg]
    markers=[(r,c) for r,row in enumerate(grid) for c,x in enumerate(row) if x not in (bg,fill,2,7,9)]
    if left:
        for r in range(min(left),max(left)+1):
            for c in range(1,w):
                if grid[r][c] not in (bg,): break
                out[r][c]=fill
