        for r in range(min(right),max(right)+1):
            for c in range(w-2,-1,-1):
                if grid[r][c]!=bg: break
                out[r][c]=fill
    # For demos with edge bars at top/bottom, extend the bar into the interior.
    top=[c for c,x in enumerate(grid[0]) if x!=bg]; bottom=[c for c,x in enumerate(grid[-1]) if x!=bg]
    for c in top:
        for r in range(1,h):
            if grid[r][c]!=bg: break
            out[r][c]=fill
    for c in bottom:
        for r in range(h-2,-1,-1):
            if grid[r][c]!=bg: break
            out[r][c]=fill
    # Extend marker trails in the appropriate direction; marker becomes 4.
    for r,c in markers:
        out[r][c]=4
        direction=-1 if left and c>0 else 1
        for cc in range(c+direction, 0 if direction<0 else w, direction):
            if grid[r][cc]!=bg: break
            out[r][cc]=fill
