def transform(grid):
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    # Long rails on edges extend inward; each rail determines fill hue
    # from the isolated colored marks in its region.
    bg=max(set(x for row in grid for x in row), key=lambda x:sum(row.count(x) for row in grid))
    # edge runs are source rails; use the non-background endpoint color
    left=[r for r in range(h) if grid[r][0]!=bg]
    right=[r for r in range(h) if grid[r][-1]!=bg]
    marks=[(r,c,v) for r,row in enumerate(grid) for c,v in enumerate(row) if v!=bg and not (c==0 and r in left) and not (c==w-1 and r in right)]
    fill=marks[0][2] if marks else 4
    # extend each rail into its inward-facing rows/columns
    if left:
        for r in range(min(left),max(left)+1):
            for c in range(1,w):
                if grid[r][c]!=bg: break
                out[r][c]=fill
    if right:
        for r in range(min(right),max(right)+1):
            for c in range(w-2,-1,-1):
                if grid[r][c]!=bg: break
                out[r][c]=fill
    # mark the ray intersections and extend away from the line ends
    for r,c,v in marks:
        out[r][c]=4
        if left and c>0:
            for rr in range(r):
                if grid[rr][c]==bg: out[rr][c]=v
        if right and c<w-1:
            for rr in range(r+1,h):
                if grid[rr][c]==bg: out[rr][c]=v
    return out
